 function monta_grid($linhas = 0)
 {
   global $nm_saida;

   clearstatcache();
   $this->NM_cor_embutida();
   $this->hide_nested_grid_action_buttons = false;
   $this->All_nested      = array();
   $this->All_nested_line = array();
   if (isset($_SESSION['scriptcase']['sc_apl_conf']['grid_acompanhantes_rsvp']['field_display']) && !empty($_SESSION['scriptcase']['sc_apl_conf']['grid_acompanhantes_rsvp']['field_display']))
   {
       foreach ($_SESSION['scriptcase']['sc_apl_conf']['grid_acompanhantes_rsvp']['field_display'] as $NM_cada_field => $NM_cada_opc)
       {
           $this->NM_cmp_hidden[$NM_cada_field] = $NM_cada_opc;
       }
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['usr_cmp_sel']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['usr_cmp_sel']))
   {
       foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['usr_cmp_sel'] as $NM_cada_field => $NM_cada_opc)
       {
           $this->NM_cmp_hidden[$NM_cada_field] = $NM_cada_opc;
       }
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['php_cmp_sel']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['php_cmp_sel']))
   {
       foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['php_cmp_sel'] as $NM_cada_field => $NM_cada_opc)
       {
           $this->NM_cmp_hidden[$NM_cada_field] = $NM_cada_opc;
       }
   }
   if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_pesq'])) {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_pesq'] = array();
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['embutida_init'])
   { 
        return; 
   } 
   $this->inicializa();
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['charts_html'] = '';
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['embutida'])
   { 
       $this->Lin_impressas = 0;
       $this->Lin_final     = FALSE;
       $this->grid($linhas);
       $this->nm_fim_grid();
   } 
   else 
   { 
    if (strpos(" " . $this->Ini->SC_module_export, "grid") !== false) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['proc_pdf'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['proc_pdf_vert'])
            {
            } 
            else
            {
                $this->cabecalho();
            } 
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['proc_pdf'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['proc_pdf_vert'])
            {
            } 
            else
            {
       $nm_saida->saida("                  <TR>\r\n");
       $nm_saida->saida("                  <TD id='sc_grid_content' style='padding: 0px;' colspan=3>\r\n");
            } 
       $nm_saida->saida("    <table width='100%' cellspacing=0 cellpadding=0>\r\n");
       $nmgrp_apl_opcao= (isset($_SESSION['sc_session']['scriptcase']['embutida_form_pdf']['grid_acompanhantes_rsvp'])) ? "pdf" : $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao'];
       $this->nmgp_barra_sub_cons = false;
       if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['SC_sub_toolbar'])) {
           if (!$_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['ExportPrtFrame']) {
               $this->nmgp_tool_subcons();
               $this->nmgp_embbed_placeholder_top();
           } 
           $this->nmgp_barra_sub_cons = true;
       } 
       if ($nmgrp_apl_opcao != "pdf" && !$this->nmgp_barra_sub_cons)
       { 
           $this->nmgp_barra_top();
       } 
       if ($nmgrp_apl_opcao != "pdf" && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao_print'] != 'print')
       { 
           if ($this->Ini->grid_search_change_fil)
           { 
               $seq_search = 1;
               foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_pesq'] as $cmp => $def)
               {
                  $Seq_grid      = $seq_search;
                  $Cmp_grid      = $cmp;
                  $Def_grid      = array('descr' => $def['descr'], 'hint' => $def['hint']);
                  $Lin_grid_add  = $this->grid_search_tag_ini($Cmp_grid, $Def_grid, $Seq_grid);
                  $NM_func_grid_add = "grid_search_" . $Cmp_grid;
                  $Lin_grid_add .= $this->$NM_func_grid_add($Seq_grid, 'S', $def['opc'], $def['val'], $nmgp_tab_label[$Cmp_grid]);
                  $Lin_grid_add .= $this->grid_search_tag_end();
                  $this->Ini->Arr_result['grid_search_add'][] = array ('field' => $cmp, 'tag' => NM_charset_to_utf8($Lin_grid_add));
                  $seq_search++;
               } 
           } 
           elseif (!$this->Proc_link_res) 
           { 
               $this->html_grid_search();
           } 
       } 
       unset ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['save_grid']);
       $this->grid();
       if ($nmgrp_apl_opcao != "pdf" && !$this->nmgp_barra_sub_cons)
       { 
           $this->nmgp_barra_bot();
       } 
       $nm_saida->saida("   </table>\r\n");
       $nm_saida->saida("  </TD>\r\n");
       $nm_saida->saida(" </TR>\r\n");
       $this->rodape();
    }
       if (strpos(" " . $this->Ini->SC_module_export, "resume") !== false)
       { 
           $Gera_res = true;
       } 
       else 
       { 
           $Gera_res = false;
       } 
       if (strpos(" " . $this->Ini->SC_module_export, "chart") !== false)
       { 
           $Gera_graf = true;
       } 
       else 
       { 
           $Gera_graf = false;
       } 
       if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['print_all'] && empty($this->nm_grid_sem_reg) && ($Gera_res || $Gera_graf) && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['SC_Ind_Groupby'] != "sc_free_total")
       { 
           $this->Res->monta_html_ini_pdf();
           $this->Res->monta_resumo();
           $this->Res->monta_html_fim_pdf();
           if ($Gera_graf)
           {
               $this->grafico_pdf();
           }
       } 
       $flag_apaga_pdf_log = TRUE;
       if (!$this->Print_All && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao'] == "pdf")
       { 
           $flag_apaga_pdf_log = FALSE;
       } 
       $this->nm_fim_grid($flag_apaga_pdf_log);
       if (!$this->Print_All && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao'] == "pdf")
       { 
           $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao'] = "igual";
       } 
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao_print'] == "print")
   {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao'] = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao_ant'];
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao_print'] = "";
   }
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao_ant'] = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opcao'];
 }
 function resume($linhas = 0)
 {
    $this->Lin_impressas = 0;
    $this->Lin_final     = FALSE;
    $this->grid($linhas);
 }
