 function inicializa()
 {
   global $nm_saida, $NM_run_iframe,
   $rec, $nmgp_chave, $nmgp_opcao, $nmgp_ordem, $nmgp_chave_det,
   $nmgp_quant_linhas, $nmgp_quant_colunas, $nmgp_url_saida, $nmgp_parms;
//
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['orig_pesq'] = "grid";
   if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['Ind_lig_mult'])) {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['Ind_lig_mult'] = 0;
   }
   $this->Img_embbed      = false;
   $this->nm_data         = new nm_data("pt_br");
   $this->pdf_label_group = (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_pdf']['label_group'])) ? $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_pdf']['label_group'] : "N";
   $this->pdf_all_cab     = (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_pdf']['all_cab']))     ? $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_pdf']['all_cab'] : "S";
   $this->pdf_all_label   = (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_pdf']['all_label']))   ? $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_pdf']['all_label'] : "S";
   $this->Fix_bar_top     = false;
   $this->Fix_bar_bottom  = false;
   $this->Grid_body       = 'id="sc_grid_body"';
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['embutida'])
   {
       $this->Grid_body = "";
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_liga']['fix_top'])) {
       $this->Fix_bar_top = ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_liga']['fix_top'] == "S") ? true : false;
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_liga']['fix_bot'])) {
       $this->Fix_bar_bottom = ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['opc_liga']['fix_bot'] == "S") ? true : false;
   }
   $this->Det_colspan = " colspan=3";
   $this->Css_Cmp = array();
   $NM_css = file($this->Ini->root . $this->Ini->path_link . "grid_acompanhantes_rsvp/grid_acompanhantes_rsvp_grid_" .strtolower($_SESSION['scriptcase']['reg_conf']['css_dir']) . ".css");
   foreach ($NM_css as $cada_css)
   {
       $Pos1 = strpos($cada_css, "{");
       $Pos2 = strpos($cada_css, "}");
       $Tag  = explode(",", trim(substr($cada_css, 1, $Pos1 - 1)));
       $Css  = substr($cada_css, $Pos1 + 1, $Pos2 - $Pos1 - 1);
       if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['doc_word'])
       { 
           $this->Css_Cmp[$Tag[0]] = $Css;
       }
       else
       { 
           $this->Css_Cmp[$Tag[0]] = "";
       }
   }
   if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label']))
   {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] = "";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_nome?#?" . "Nome" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_ativo?#?" . "Ativo" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_sexo?#?" . "Part Sexo" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_cpf?#?" . "Cód. Acomp." . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_cpf_mestre?#?" . "CPF Partic." . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_id_evento_publico?#?" . "Part Id Evento Publico" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_id_evento_regional?#?" . "Part Id Evento Regional" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_empresa?#?" . "Part Empresa" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_aereo?#?" . "Part Aereo" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_hospedagem?#?" . "Part Hospedagem" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_transfer?#?" . "Part Transfer" . "?@?";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'] .= "part_opcionais?#?" . "Part Opcionais" . "?@?";
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_search_add']))
   {
       $nmgp_tab_label = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['pesq_tab_label'];
       if (!empty($nmgp_tab_label))
       {
          $nm_tab_campos = explode("?@?", $nmgp_tab_label);
          $nmgp_tab_label = array();
          foreach ($nm_tab_campos as $cada_campo)
          {
              $parte_campo = explode("?#?", $cada_campo);
              $nmgp_tab_label[$parte_campo[0]] = $parte_campo[1];
          }
       }
       $Seq_grid      = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_search_add']['seq'];
       $Cmp_grid      = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_search_add']['cmp'];
       $Def_grid      = array('descr' => $nmgp_tab_label[$Cmp_grid], 'hint' => $nmgp_tab_label[$Cmp_grid]);
       $Lin_grid_add  = $this->grid_search_tag_ini($Cmp_grid, $Def_grid, $Seq_grid);
       $NM_func_grid_add = "grid_search_" . $Cmp_grid;
       $Lin_grid_add .= $this->$NM_func_grid_add($Seq_grid, 'S', '', array(), $nmgp_tab_label[$Cmp_grid]);
       $Lin_grid_add .= $this->grid_search_tag_end();
       $this->Arr_result = array();
       $Temp = ob_get_clean();
       if ($Temp !== false && trim($Temp) != "")
       {
           $this->Arr_result['htmOutput'] = NM_charset_to_utf8($Temp);
       }
       $this->Arr_result['grid_add'][] = NM_charset_to_utf8($Lin_grid_add);
       $oJson = new Services_JSON();
       echo $oJson->encode($this->Arr_result);
       unset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['grid_search_add']);
       exit;
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['dyn_search_aut_comp']))
   {
       $NM_func_aut_comp = "lookup_ajax_" . $_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['dyn_search_aut_comp']['cmp'];
       $parm = ($_SESSION['scriptcase']['charset'] != "UTF-8" && NM_is_utf8($_GET['q'])) ? sc_convert_encoding($_GET['q'], $_SESSION['scriptcase']['charset'], "UTF-8") : $_GET['q'];
       $nmgp_def_dados = $this->$NM_func_aut_comp($parm);
       ob_end_clean();
       $count_aut_comp = 0;
       $resp_aut_comp  = array();
       foreach ($nmgp_def_dados as $Ind => $Lista)
       {
          if (is_array($Lista))
          {
              foreach ($Lista as $Cod => $Valor)
              {
