        $nm_saida->saida("        setTimeout(function() { doResizeNestedGridIframe(); }, 50);\r\n");
        $nm_saida->saida("    }\r\n");
        $nm_saida->saida("    function doResizeNestedGridIframe()\r\n");
        $nm_saida->saida("    {\r\n");
        $nm_saida->saida("        const iframe = window.frameElement;\r\n");
        $nm_saida->saida("        if (!iframe || window._scNestedResizing) {\r\n");
        $nm_saida->saida("            return;\r\n");
        $nm_saida->saida("        }\r\n");
        $nm_saida->saida("        window._scNestedResizing = true;\r\n");
        $nm_saida->saida("        try {\r\n");
        $nm_saida->saida("            iframe.style.height = '1px';\r\n");
        $nm_saida->saida("            const newHeight = Math.max(document.body.scrollHeight || 0, document.documentElement.scrollHeight || 0);\r\n");
        $nm_saida->saida("            if (newHeight > 1) {\r\n");
        $nm_saida->saida("                iframe.style.height = newHeight + 'px';\r\n");
        $nm_saida->saida("                if (\"function\" == typeof window.parent.resizeNestedGridIframe) {\r\n");
        $nm_saida->saida("                    window.parent.resizeNestedGridIframe();\r\n");
        $nm_saida->saida("                }\r\n");
        $nm_saida->saida("            }\r\n");
        $nm_saida->saida("        } finally {\r\n");
        $nm_saida->saida("            setTimeout(function() { window._scNestedResizing = false; }, 150);\r\n");
        $nm_saida->saida("        }\r\n");
        $nm_saida->saida("    }\r\n");
        $nm_saida->saida("    window.addEventListener('load', resizeNestedGridIframe);\r\n");
        $nm_saida->saida("    new ResizeObserver(resizeNestedGridIframe).observe(document.body);\r\n");
        $nm_saida->saida("</script>\r\n");
    }
 }  

