                !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['dyn_search'])
            )
            {
                foreach($_SESSION['sc_session'][$this->Ini->sc_page]['grid_acompanhantes_rsvp']['dyn_search'] as $_fld)
                {
                    if($_fld['cmp'] == $field)
