                               $str_value = $str_html_ini. $str_value .$str_html_fim;
                            }
                        }
                        elseif($_fld['opc'] == 'ii')
                        {
                            if(strcasecmp($vals, substr($str_value, 0, strlen($vals))) == 0)
                            {
                                $str_value = $str_html_ini. substr($str_value, 0, strlen($vals)) .$str_html_fim . substr($str_value, strlen($vals));
